param([string]$CaseId='')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$base='http://192.168.122.1:8872';$root='C:\JudasValidation'
function Upload($p,$n){for($attempt=0;$attempt -lt 10;$attempt++){try{Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null;return}catch{if($attempt -eq 9){throw};Start-Sleep -Milliseconds 200}}}
$m=(Invoke-WebRequest -UseBasicParsing "$base/m78-closure-v1.json").Content|ConvertFrom-Json;$s=$m.scratch;$o=$m.output;$c=@($m.cases|Where-Object {$_.id -eq $CaseId});if($c.Count -ne 1){throw 'Unique existing completed case required'};$c=$c[0];$rp="$o\m78-closure-$CaseId-build.json";if(Test-Path $rp){throw 'Existing receipt must remain'}
$engine=[IO.File]::ReadAllText("$o\m78-closure-engine.json")|ConvertFrom-Json;$exe="$root\Build\Release\m78-closure-$CaseId.exe";if(@(Get-Process|Where-Object {$_.Path -eq $exe}).Count){throw 'Owned case still running'};$runs=@();foreach($r in $c.runs){$p="$o\m78-closure-$($r.id).json";$v=[IO.File]::ReadAllText($p)|ConvertFrom-Json;if($v.executableSHA256 -ne (Get-FileHash $exe).Hash.ToLower()){throw 'Completed run identity mismatch'};$runs+=$v}
$rows=@();$files=@();foreach($u in $c.inputs){$obj="$s\objects\$($u.objectName)";$rows+=@{path=$obj;name=[IO.Path]::GetFileName($obj);bytes=(Get-Item $obj).Length;sha256=(Get-FileHash $obj).Hash.ToLower();source=$u.path;sourceSHA256=$u.sha256;reuseOriginal=$u.reuseOriginal}}
$map="$o\m78-closure-$CaseId.map";$log="$o\m78-closure-$CaseId-link.log";if([IO.File]::ReadAllText($log) -match '(?im)^\s*Loaded\s+.*judas_engine\.lib\([^\)\r\n]*(PhysicsWorld|WorldPersistence)\.obj\)'){throw 'Unexpected frozen replaced member extracted'}
foreach($p in @($exe)+@($rows|ForEach-Object {$_.path})){$files+=@{path=$p;name=[IO.Path]::GetFileName($p);bytes=(Get-Item $p).Length;sha256=(Get-FileHash $p).Hash.ToLower()};Upload $p ('m78-closure-'+$CaseId+'-'+[IO.Path]::GetFileName($p)+'.bin')}
@{scope=$m.scope;archivalRecovery='Only artifact transfer retried after passed completed run; no compile/link/simulation rerun';case=$CaseId;reusedOrFreshInputs=$rows;archive=$engine.archive;replacementObjects=$engine.objects;executable=$exe;executableSHA256=(Get-FileHash $exe).Hash.ToLower();executableBytes=(Get-Item $exe).Length;linkerResponse=[IO.File]::ReadAllText("$s\objects\$CaseId-link.rsp");mapSHA256=(Get-FileHash $map).Hash.ToLower();frozenReplacedMembersNotExtracted=$true;runs=$runs;generatedFiles=$files;ownedLargeEvidence=@($map,$log)|ForEach-Object {@{path=$_;name=[IO.Path]::GetFileName($_);bytes=(Get-Item $_).Length;sha256=(Get-FileHash $_).Hash.ToLower()}};freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 8|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp))
